package day2;

public class _99_증감연산_연습문제 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int a = 5; // a = 5;
		int b = --a; // b = 4, a = 4;
		int c = b++; // c = 4, b = 5, a = 4;
		int d = ++a; // d = 5, c = 4, b = 5, a = 5;
		int e = c--; // e = 4, d = 5, c = 3, b = 5, a = 5;
		c = ++a; // e = 4, d = 5, c = 6, b = 5, a = 6;
		
		// a,b,c,d,e 값을 추론해서 메모장에 작성
		// a=6, b=5, c=6, d=5, e=4;
		
		
		
	}

}
